import React, { useState, useEffect, useRef, useCallback } from 'react';
import io from 'socket.io-client';
import { Avatar3D } from '../components/Avatar3D';
import { DraggableUserVideo } from '../components/DraggableUserVideo';
import { ShareModal } from '../components/ShareModal';
import { VideoPlayerModal } from '../components/VideoPlayerModal';
import { SidePanel } from '../components/SidePanel';
import { CallControls } from '../components/CallControls';
import { useVoiceInput } from '../hooks/useVoiceInput';
import { sendChatMessage } from '../utils/api';
import { speakText, stopSpeaking } from '../utils/speechSynthesis';
import toast, { Toaster } from 'react-hot-toast';

const socket = io('http://localhost:8000', {
  transports: ['websocket'],
  reconnection: true,
  reconnectionAttempts: 5,
  reconnectionDelay: 1000,
});

// ✅ CLEAN TEXT: Remove emojis and unwanted characters
const cleanTextForSpeech = (text) => {
  if (!text) return '';
  return text
    .replace(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[👋👍❤️🎉😂🔥💪✨🌟💯🎯🎊🎈🎨📝💬👥]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

// ✅ FIXED VOICE SELECTION - Separate male and female voices
let CACHED_MALE_VOICE = null;
let CACHED_FEMALE_VOICE = null;

const initializeVoices = () => {
  const voices = window.speechSynthesis.getVoices();
  
  if (!CACHED_MALE_VOICE) {
    // Find ACTUAL male voice
    CACHED_MALE_VOICE =
      voices.find(v => v.name.includes('Male') || v.name.includes('David') || v.name.includes('Daniel')) ||
      voices.find(v => v.name === 'Microsoft David - English (United States)') ||
      voices.find(v => v.name === 'Google UK English Male') ||
      voices.find(v => v.name.includes('Guy') || v.name.includes('Male')) ||
      voices.find(v => v.lang.startsWith('en') && !v.name.includes('Female') && !v.name.includes('Samantha')) ||
      voices[0];
  }

  if (!CACHED_FEMALE_VOICE) {
    // Find ACTUAL female voice
    CACHED_FEMALE_VOICE =
      voices.find(v => v.name.includes('Female') || v.name.includes('Samantha') || v.name.includes('Victoria')) ||
      voices.find(v => v.name === 'Microsoft Zira - English (United States)') ||
      voices.find(v => v.name === 'Google UK English Female') ||
      voices.find(v => v.name.includes('Karen') || v.name.includes('Susan')) ||
      voices.find(v => v.lang.startsWith('en') && !v.name.includes('Male')) ||
      voices[1];
  }

  console.log('🎤 Cached Male Voice:', CACHED_MALE_VOICE?.name);
  console.log('🎤 Cached Female Voice:', CACHED_FEMALE_VOICE?.name);
};

export const VideoCallPage = ({ companion, roomId, userId, onEndCall }) => {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(false);
  const [mediaStream, setMediaStream] = useState(null);
  const [isCameraLoading, setIsCameraLoading] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState(null);
  const [callTime, setCallTime] = useState(0);
  const [isRecording, setIsRecording] = useState(false);
  const [isShareModalOpen, setShareModalOpen] = useState(false);
  const [activePanel, setActivePanel] = useState('chat');
  const [isMenuOpen, setMenuOpen] = useState(false);
  const [reactions, setReactions] = useState([]);
  const [playingVideoId, setPlayingVideoId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [currentAudio, setCurrentAudio] = useState(null);
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [currentSpeakingText, setCurrentSpeakingText] = useState('');
  const [hasPlayedIntro, setHasPlayedIntro] = useState(false);
  const [customAnimation, setCustomAnimation] = useState(null);
  const [participants, setParticipants] = useState([]);
  const [remoteStreams, setRemoteStreams] = useState({});

  const peerConnections = useRef({});
  const hasJoinedRoom = useRef(false);
  const userVideoRef = useRef(null);
  const screenVideoRef = useRef(null);
  const synth = useRef(null);
  const mediaStreamRef = useRef(null);
  const screenStreamRef = useRef(null);
  const timerRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);
  const currentUtteranceRef = useRef(null);
  const isCurrentlySpeakingRef = useRef(false);

  const getCompanionId = useCallback(() => {
    return companion?.id || 'omkar_ai';
  }, [companion]);

  const handlePlayAnimation = useCallback((animationId) => {
    console.log('🎮 Playing animation:', animationId);
    setCustomAnimation(animationId);
    setTimeout(() => setCustomAnimation(null), 8000);
  }, []);

  // ✅ COMPLETE STOP - Works ALWAYS
  const handleStopAI = useCallback(() => {
    console.log('⏹️ STOPPING AI COMPLETELY');
    isCurrentlySpeakingRef.current = false;

    // Stop TTS
    window.speechSynthesis.cancel();
    if (currentUtteranceRef.current) {
      currentUtteranceRef.current = null;
    }

    // Stop audio
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
      currentAudio.src = '';
      currentAudio.load();
      setCurrentAudio(null);
    }

    setIsAISpeaking(false);
    setCurrentSpeakingText('');
    console.log('✅ AI STOPPED');
  }, [currentAudio]);

  // ✅ FIXED: Proper voice selection based on avatar gender
  const speakWithCorrectVoice = useCallback((text, isFemale) => {
    return new Promise((resolve, reject) => {
      const cleanedText = cleanTextForSpeech(text);
      if (!cleanedText) {
        resolve();
        return;
      }

      console.log(`🗣️ Speaking with ${isFemale ? 'FEMALE' : 'MALE'} voice:`, cleanedText.substring(0, 50) + '...');
      window.speechSynthesis.cancel();

      const utterance = new SpeechSynthesisUtterance(cleanedText);

      // ✅ FIXED: Use correct voice based on avatar gender
      const selectedVoice = isFemale ? CACHED_FEMALE_VOICE : CACHED_MALE_VOICE;
      
      if (selectedVoice) {
        utterance.voice = selectedVoice;
        console.log('🎤 Using voice:', selectedVoice.name, '| isFemale:', isFemale);
      }

      utterance.rate = 0.95;
      utterance.pitch = isFemale ? 1.1 : 0.9; // Higher pitch for female, lower for male
      utterance.volume = 1.0;
      utterance.lang = 'en-US';

      utterance.onstart = () => {
        isCurrentlySpeakingRef.current = true;
        setIsAISpeaking(true);
        setCurrentSpeakingText(cleanedText);
      };

      utterance.onend = () => {
        if (isCurrentlySpeakingRef.current) {
          isCurrentlySpeakingRef.current = false;
          setIsAISpeaking(false);
          setCurrentSpeakingText('');
          currentUtteranceRef.current = null;
          resolve();
        }
      };

      utterance.onerror = (err) => {
        console.error('❌ TTS error:', err);
        isCurrentlySpeakingRef.current = false;
        setIsAISpeaking(false);
        setCurrentSpeakingText('');
        currentUtteranceRef.current = null;
        reject(err);
      };

      currentUtteranceRef.current = utterance;
      setTimeout(() => {
        if (isCurrentlySpeakingRef.current) {
          window.speechSynthesis.speak(utterance);
        }
      }, 100);
    });
  }, []);

  // ✅ FIXED: Always use correct voice based on avatar
  const playAudio = useCallback(
    async (audioUrl, fullText) => {
      try {
        // Stop any current speech
        if (isCurrentlySpeakingRef.current) {
          handleStopAI();
          await new Promise(resolve => setTimeout(resolve, 200));
        }

        if (currentAudio) {
          currentAudio.pause();
          currentAudio.src = '';
          currentAudio.load();
          setCurrentAudio(null);
        }

        const isFemale = getCompanionId() === 'priya_biology';
        isCurrentlySpeakingRef.current = true;

        if (!audioUrl) {
          console.log('🔊 Using TTS with correct voice');
          await speakWithCorrectVoice(fullText, isFemale);
          return;
        }

        console.log('🎵 Playing audio from URL');
        setCurrentSpeakingText(fullText);
        setIsAISpeaking(true);

        const audio = new Audio(audioUrl);
        setCurrentAudio(audio);

        audio.onended = () => {
          console.log('✅ Audio ended');
          audio.src = '';
          audio.load();
          setCurrentAudio(null);
          isCurrentlySpeakingRef.current = false;
          setIsAISpeaking(false);
          setCurrentSpeakingText('');
        };

        audio.onerror = async (err) => {
          console.error('❌ Audio failed, using TTS:', err);
          try {
            await speakWithCorrectVoice(fullText, isFemale);
          } catch (ttsErr) {
            console.error('TTS fallback failed:', ttsErr);
          }
          isCurrentlySpeakingRef.current = false;
          setIsAISpeaking(false);
          setCurrentSpeakingText('');
        };

        await audio.play();
      } catch (error) {
        console.error('❌ Error playing audio:', error);
        isCurrentlySpeakingRef.current = false;
        setIsAISpeaking(false);
        setCurrentSpeakingText('');
      }
    },
    [currentAudio, getCompanionId, handleStopAI, speakWithCorrectVoice]
  );

  const getMedia = useCallback(
    async (opts = { video: true, audio: true }) => {
      setIsCameraLoading(true);
      try {
        const stream = await navigator.mediaDevices.getUserMedia(opts);
        setMediaStream(stream);
        mediaStreamRef.current = stream;
        if (userVideoRef.current && !isVideoOff) {
          userVideoRef.current.srcObject = stream;
          const p = userVideoRef.current.play();
          if (p && p.catch) p.catch(() => {});
        }
        console.log('✅ Camera initialized');
        return stream;
      } catch (err) {
        console.error('❌ Error accessing media devices:', err);
        toast.error('Could not access camera/microphone');
        return null;
      } finally {
        setIsCameraLoading(false);
      }
    },
    [isVideoOff]
  );

  const createPeerConnection = useCallback((targetUserId, stream) => {
    const configuration = {
      iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'stun:stun1.l.google.com:19302' },
        {
          urls: [
            'turn:openrelay.metered.ca:80',
            'turn:openrelay.metered.ca:443',
            'turn:openrelay.metered.ca:443?transport=tcp'
          ],
          username: 'openrelayproject',
          credential: 'openrelayproject'
        }
      ],
      iceCandidatePoolSize: 10,
    };

    const pc = new RTCPeerConnection(configuration);
    peerConnections.current[targetUserId] = pc;

    if (stream) {
      stream.getTracks().forEach((track) => {
        pc.addTrack(track, stream);
      });
    }

    pc.ontrack = (event) => {
      console.log('🎥 Received remote stream from:', targetUserId);
      setRemoteStreams((prev) => ({
        ...prev,
        [targetUserId]: event.streams[0],
      }));
    };

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        socket.emit('ice-candidate', {
          roomId,
          candidate: event.candidate,
          targetUserId,
          fromUserId: userId,
        });
      }
    };

    return pc;
  }, [roomId, userId]);

  const handleRecordingToggle = async () => {
    if (!isRecording) {
      try {
        const displayStream = await navigator.mediaDevices.getDisplayMedia({
          video: { mediaSource: 'screen', width: 1920, height: 1080, frameRate: 30 },
          audio: { echoCancellation: false, noiseSuppression: false, sampleRate: 48000 }
        });

        const audioContext = new (window.AudioContext || window.webkitAudioContext)();
        const destination = audioContext.createMediaStreamDestination();

        if (displayStream.getAudioTracks().length > 0) {
          const systemSource = audioContext.createMediaStreamSource(displayStream);
          systemSource.connect(destination);
        }

        if (mediaStream?.getAudioTracks().length > 0) {
          const micSource = audioContext.createMediaStreamSource(mediaStream);
          micSource.connect(destination);
        }

        const combinedStream = new MediaStream([
          displayStream.getVideoTracks()[0],
          ...destination.stream.getAudioTracks()
        ]);

        mediaRecorderRef.current = new MediaRecorder(combinedStream, {
          mimeType: 'video/webm;codecs=vp9,opus',
          videoBitsPerSecond: 2500000,
          audioBitsPerSecond: 128000
        });

        recordedChunksRef.current = [];

        mediaRecorderRef.current.ondataavailable = (e) => {
          if (e.data && e.data.size > 0) {
            recordedChunksRef.current.push(e.data);
          }
        };

        mediaRecorderRef.current.onstop = () => {
          const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `saarthi-${Date.now()}.webm`;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          URL.revokeObjectURL(url);
          displayStream.getTracks().forEach(t => t.stop());
          audioContext.close();
          toast.success('📹 Recording saved!');
        };

        mediaRecorderRef.current.start(100);
        setIsRecording(true);
        toast.success('🔴 Recording started');

        displayStream.getVideoTracks()[0].onended = () => {
          if (mediaRecorderRef.current?.state === 'recording') {
            mediaRecorderRef.current.stop();
            setIsRecording(false);
          }
        };
      } catch (err) {
        console.error('❌ Recording error:', err);
        toast.error('Recording failed');
      }
    } else {
      if (mediaRecorderRef.current?.state === 'recording') {
        mediaRecorderRef.current.stop();
        setIsRecording(false);
      }
    }
  };

  // Initialize voices on mount
  useEffect(() => {
    initializeVoices();
    window.speechSynthesis.onvoiceschanged = initializeVoices;
  }, []);

  useEffect(() => {
    let mounted = true;

    const initWebRTC = async () => {
      const stream = await getMedia({ video: true, audio: true });
      if (!stream || !mounted) return;

      await new Promise(resolve => setTimeout(resolve, 500));

      if (!hasJoinedRoom.current) {
        hasJoinedRoom.current = true;
        socket.emit('join-room', { roomId, userId, companionId: companion?.id });

        socket.on('user-joined', (data) => {
          toast.success(`${data.userId.substring(0, 15)}... joined`, { duration: 2000, icon: '👋' });
          setParticipants((prev) => {
            if (prev.some(p => p.userId === data.userId)) return prev;
            return [...prev, { userId: data.userId, joinedAt: Date.now() }];
          });

          const pc = createPeerConnection(data.userId, stream);
          pc.createOffer()
            .then((offer) => pc.setLocalDescription(offer))
            .then(() => {
              socket.emit('offer', {
                roomId,
                offer: pc.localDescription,
                targetUserId: data.userId,
                fromUserId: userId,
              });
            });
        });

        socket.on('existing-users', (users) => {
          setParticipants(users.map(u => ({ userId: u, joinedAt: Date.now() })));
        });

        socket.on('user-left', (data) => {
          setParticipants((prev) => prev.filter((p) => p.userId !== data.userId));
          setRemoteStreams((prev) => {
            const newStreams = { ...prev };
            delete newStreams[data.userId];
            return newStreams;
          });
          if (peerConnections.current[data.userId]) {
            peerConnections.current[data.userId].close();
            delete peerConnections.current[data.userId];
          }
        });

        socket.on('offer', async (data) => {
          const { offer, fromUserId } = data;
          const pc = createPeerConnection(fromUserId, stream);
          await pc.setRemoteDescription(new RTCSessionDescription(offer));
          const answer = await pc.createAnswer();
          await pc.setLocalDescription(answer);
          socket.emit('answer', {
            roomId,
            answer,
            targetUserId: fromUserId,
            fromUserId: userId,
          });
        });

        socket.on('answer', async (data) => {
          const { answer, fromUserId } = data;
          const pc = peerConnections.current[fromUserId];
          if (pc && pc.signalingState === 'have-local-offer') {
            await pc.setRemoteDescription(new RTCSessionDescription(answer));
          }
        });

        socket.on('ice-candidate', async (data) => {
          const { candidate, fromUserId } = data;
          const pc = peerConnections.current[fromUserId];
          if (pc && pc.remoteDescription) {
            try {
              await pc.addIceCandidate(new RTCIceCandidate(candidate));
            } catch (err) {
              console.error('ICE error:', err);
            }
          }
        });

        socket.on('chat-message', (data) => {
          const newMessage = {
            sender: data.sender,
            text: data.message,
            timestamp: data.timestamp,
            userId: data.userId,
          };

          setMessages((prev) => {
            if (prev.some(m => m.timestamp === data.timestamp && m.userId === data.userId)) {
              return prev;
            }
            return [...prev, newMessage];
          });
        });
      }
    };

    initWebRTC();

    if (window.Tone) {
      try {
        synth.current = new window.Tone.PolySynth().toDestination();
      } catch (e) {}
    }

    timerRef.current = setInterval(() => setCallTime((t) => t + 1), 1000);

    return () => {
      mounted = false;
      hasJoinedRoom.current = false;
      clearInterval(timerRef.current);
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach((t) => t.stop());
      }
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach((t) => t.stop());
      }
      window.speechSynthesis.cancel();
      if (currentAudio) currentAudio.pause();
      Object.values(peerConnections.current).forEach((pc) => {
        try { pc.close(); } catch (e) {}
      });
      socket.emit('leave-room', { roomId, userId });
      socket.off('user-joined');
      socket.off('user-left');
      socket.off('existing-users');
      socket.off('offer');
      socket.off('answer');
      socket.off('ice-candidate');
      socket.off('chat-message');
    };
  }, [roomId, userId, companion?.id, getMedia, createPeerConnection, currentAudio]);

  useEffect(() => {
    mediaStreamRef.current = mediaStream;
    if (userVideoRef.current && mediaStream) {
      userVideoRef.current.srcObject = mediaStream;
      const p = userVideoRef.current.play();
      if (p && p.catch) p.catch(() => {});
    }
  }, [mediaStream]);

  useEffect(() => {
    screenStreamRef.current = screenStream;
    if (screenVideoRef.current && screenStream) {
      screenVideoRef.current.srcObject = screenStream;
      const p = screenVideoRef.current.play();
      if (p && p.catch) p.catch(() => {});
    }
  }, [screenStream]);

  useEffect(() => {
    if (!mediaStream) return;
    mediaStream.getAudioTracks().forEach((track) => {
      track.enabled = !isMuted;
    });
    mediaStream.getVideoTracks().forEach((track) => {
      track.enabled = !isVideoOff;
    });
  }, [isMuted, isVideoOff, mediaStream]);

  const toggleScreenShare = async () => {
    if (isScreenSharing) {
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach((track) => track.stop());
      }
      setScreenStream(null);
      setIsScreenSharing(false);
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        screenStreamRef.current = stream;
        setIsScreenSharing(true);
        stream.getVideoTracks()[0].onended = () => {
          setScreenStream(null);
          screenStreamRef.current = null;
          setIsScreenSharing(false);
        };
      } catch (err) {
        console.error('Screen share error:', err);
      }
    }
  };

  const sendReaction = (emoji) => {
    if (synth.current) {
      const notes = { '👍': 'C4', '❤️': 'E4', '🎉': 'G4', '😂': 'A4' };
      try {
        synth.current.triggerAttackRelease(notes[emoji] || 'C5', '8n');
      } catch (e) {}
    }

    const newReaction = { id: Date.now(), emoji, left: Math.random() * 80 + 10 };
    setReactions((prev) => [...prev, newReaction]);
    setTimeout(() => setReactions((prev) => prev.filter((r) => r.id !== newReaction.id)), 4000);
  };

  const handleIntroComplete = useCallback(
    async (introData) => {
      if (!hasPlayedIntro && introData) {
        setHasPlayedIntro(true);
        setTimeout(async () => {
          const introMsg = {
            sender: 'ai',
            text: introData.message,
            timestamp: new Date().toISOString(),
            source: 'intro',
          };
          setMessages([introMsg]);
          await playAudio(null, introData.message);
        }, 1500);
      }
    },
    [hasPlayedIntro, playAudio]
  );

  const handleVoiceResult = useCallback(
    async (transcript) => {
      if (!transcript?.trim()) return;

      const userMessage = {
        sender: 'user',
        text: transcript,
        timestamp: new Date().toISOString(),
        userId: userId,
      };

      setMessages((prev) => [...prev, userMessage]);
      socket.emit('chat-message', {
        roomId,
        userId,
        message: transcript,
        sender: 'user',
        timestamp: userMessage.timestamp,
      });

      try {
        const chatHistory = messages.slice(-10).map(m => ({
          role: m.sender === 'user' ? 'user' : 'assistant',
          content: m.text
        }));

        const response = await sendChatMessage(
          transcript,
          companion.id,
          roomId,
          companion.subject || 'General',
          0,
          chatHistory
        );

        const aiTimestamp = new Date().toISOString();
        const aiMessage = {
          sender: 'ai',
          text: response.text || response.message || 'I received your message.',
          timestamp: aiTimestamp,
          source: response.source || 'gemini',
          userId: companion.id,
        };

        setMessages((prev) => [...prev, aiMessage]);
        socket.emit('chat-message', {
          roomId,
          userId: companion.id,
          message: aiMessage.text,
          sender: 'ai',
          timestamp: aiTimestamp,
        });

        await playAudio(response.audioUrl, aiMessage.text);
      } catch (error) {
        console.error('Error in voice chat:', error);
        const errorMessage = {
          sender: 'ai',
          text: 'Sorry, I encountered an error.',
          timestamp: new Date().toISOString(),
        };
        setMessages((prev) => [...prev, errorMessage]);
        await playAudio(null, errorMessage.text);
      }
    },
    [companion, roomId, playAudio, userId, messages]
  );

  const { isListening, startListening, stopListening } = useVoiceInput({
    onResult: handleVoiceResult,
    language: 'en-US',
  });

  const handleSendMessage = async (text) => {
    if (!text?.trim()) return;

    const timestamp = new Date().toISOString();
    const userMessage = {
      sender: 'user',
      text,
      timestamp,
      userId: userId,
    };

    setMessages((prev) => [...prev, userMessage]);
    socket.emit('chat-message', {
      roomId,
      userId,
      message: text,
      sender: 'user',
      timestamp,
    });

    try {
      const chatHistory = messages.slice(-10).map(m => ({
        role: m.sender === 'user' ? 'user' : 'assistant',
        content: m.text
      }));

      const response = await sendChatMessage(
        text,
        companion.id,
        roomId,
        companion.subject || 'General',
        0,
        chatHistory
      );

      const aiTimestamp = new Date().toISOString();
      const aiMessage = {
        sender: 'ai',
        text: response.text || response.message || 'I received your message.',
        timestamp: aiTimestamp,
        source: response.source || 'gemini',
        userId: companion.id,
      };

      setMessages((prev) => [...prev, aiMessage]);
      socket.emit('chat-message', {
        roomId,
        userId: companion.id,
        message: aiMessage.text,
        sender: 'ai',
        timestamp: aiTimestamp,
      });

      await playAudio(response.audioUrl, aiMessage.text);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const formatTime = (seconds) =>
    `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}`;

  return (
    <>
      <Toaster position="top-center" />
      <div className="flex flex-col h-screen bg-gradient-to-br from-slate-950 via-purple-950 to-slate-950 text-white">
        <header className="flex items-center justify-between px-6 py-4 bg-black/30 backdrop-blur-md border-b border-purple-500/20">
          <div className="flex items-center space-x-4">
            <div className="w-12 h-12 rounded-full bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center font-bold text-lg">
              {companion?.name?.[0] || 'S'}
            </div>
            <div>
              <h1 className="text-xl font-bold">{companion?.name || 'Saarthi AI'}</h1>
              <p className="text-sm text-purple-300">{companion?.subject || 'AI Tutor'}</p>
            </div>
          </div>

          <div className="flex items-center space-x-6">
            <div className="flex items-center space-x-2 px-4 py-2 bg-purple-500/20 rounded-full border border-purple-400/30">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
              <span className="text-sm font-medium">{formatTime(callTime)}</span>
            </div>

            <button
              onClick={() => setShareModalOpen(true)}
              className="px-4 py-2 bg-purple-600 hover:bg-purple-700 rounded-lg font-medium transition-all"
            >
              📤 Share Room
            </button>

            <button
              onClick={onEndCall}
              className="px-4 py-2 bg-red-600 hover:bg-red-700 rounded-lg font-medium transition-all"
            >
              📞 End Call
            </button>
          </div>
        </header>

        <div className="flex flex-1 overflow-hidden">
          <div className="flex-1 relative">
            <Avatar3D
              isLoading={false}
              companion={companion}
              customAnimation={customAnimation}
              isAISpeaking={isAISpeaking}
              currentSpeakingText={currentSpeakingText}
              onIntroComplete={handleIntroComplete}
            />

            <DraggableUserVideo
              videoRef={userVideoRef}
              isVideoOff={isVideoOff}
              isMuted={isMuted}
              userName="You"
            />

            {isScreenSharing && screenStream && (
              <div className="absolute top-4 right-4 w-64 h-48 bg-black rounded-lg overflow-hidden border-2 border-purple-500 shadow-2xl">
                <video
                  ref={screenVideoRef}
                  autoPlay
                  playsInline
                  className="w-full h-full object-contain"
                />
                <div className="absolute top-2 left-2 px-2 py-1 bg-red-600 text-white text-xs rounded font-bold">
                  Screen Sharing
                </div>
              </div>
            )}
          </div>

          <SidePanel
            activePanel={activePanel}
            setActivePanel={setActivePanel}
            messages={messages}
            onSendMessage={handleSendMessage}
            participants={participants}
            roomId={roomId}
            // ✅ REMOVED: onPlayAudio prop completely removed
            onPlayAnimation={handlePlayAnimation}
          />
        </div>

        <CallControls
          isMuted={isMuted}
          toggleMute={() => setIsMuted(!isMuted)}
          isVideoOff={isVideoOff}
          toggleVideo={() => setIsVideoOff(!isVideoOff)}
          isScreenSharing={isScreenSharing}
          toggleScreenShare={toggleScreenShare}
          isRecording={isRecording}
          toggleRecording={handleRecordingToggle}
          isListening={isListening}
          startListening={startListening}
          stopListening={stopListening}
          isAISpeaking={isAISpeaking}
          stopAI={handleStopAI}
          sendReaction={sendReaction}
          activePanel={activePanel}
          setActivePanel={setActivePanel}
          onEndCall={onEndCall}
        />

        {reactions.map((reaction) => (
          <div
            key={reaction.id}
            className="fixed bottom-24 text-6xl pointer-events-none animate-float-up z-50"
            style={{ left: `${reaction.left}%` }}
          >
            {reaction.emoji}
          </div>
        ))}
      </div>

      {isShareModalOpen && (
        <ShareModal
          roomId={roomId}
          onClose={() => setShareModalOpen(false)}
        />
      )}

      {playingVideoId && (
        <VideoPlayerModal
          videoId={playingVideoId}
          onClose={() => setPlayingVideoId(null)}
        />
      )}
    </>
  );
};

export default VideoCallPage;
